// src/components/SignInModal.jsx
import React, { useState } from 'react';
import { useAuth } from '../AuthContext.jsx';
import AuthLogo from './AuthLogo.jsx';

const SignInModal = ({
  isOpen,
  onClose,
  onSwitchToSignUp,
  onSwitchToForgot,              // forgot password
  onSwitchToForgotUsername,      // ✅ NEW: forgot username
}) => {
  const { signIn } = useAuth();

  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [err, setErr] = useState('');

  if (!isOpen) return null;

  const doSignIn = (e) => {
    e.preventDefault();
    if (!username || !password) {
      setErr('Please fill in all fields');
      return;
    }
    const ok = signIn(username, password);
    if (!ok) {
      setErr('Invalid username or password');
      return;
    }
    setErr('');
    onClose?.(); // stay on LaunchPage
  };

  return (
    <div className="fixed inset-0 z-[1000] flex items-center justify-center bg-slate-950/60 backdrop-blur-sm">
      <div className="bg-white/95 backdrop-blur-md p-6 md:p-8 rounded-3xl shadow-2xl border border-slate-100 max-w-md w-full mx-4 relative">
        <button
          onClick={onClose}
          aria-label="Close modal"
          className="absolute top-3 right-3 w-9 h-9 grid place-items-center rounded-full bg-white/80 hover:bg-white shadow border border-slate-200 text-slate-600"
        >
          ✕
        </button>

        {/* ✅ Logo at top */}
        <AuthLogo size={96} />

        <form onSubmit={doSignIn}>
          <h2 className="text-2xl font-semibold text-slate-900 mb-1 text-center">Sign In</h2>
          <p className="text-sm text-slate-600 mb-5 text-center">Welcome back to TutorSimula</p>

          <div className="mb-4">
            <input
              type="text"
              placeholder="Username"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              className="w-full h-11 px-4 rounded-xl bg-white text-slate-900 placeholder-slate-400 ring-1 ring-slate-200 focus:ring-2 focus:ring-sky-400/60 focus:outline-none shadow-inner transition"
            />
          </div>

          <div className="mb-4">
            <input
              type="password"
              autoComplete="current-password"
              placeholder="Password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full h-11 px-4 rounded-xl bg-white text-slate-900 placeholder-slate-400 ring-1 ring-slate-200 focus:ring-2 focus:ring-sky-400/60 focus:outline-none shadow-inner transition"
            />
          </div>

          {err && <p className="text-red-600 text-sm mb-4 text-center">{err}</p>}

          <div className="flex justify-center gap-3">
            <button
              type="submit"
              className="w-full h-11 rounded-xl bg-gradient-to-r from-indigo-600 to-sky-500 text-white font-semibold shadow-lg shadow-sky-500/20 hover:from-indigo-500 hover:to-sky-400 focus:outline-none focus:ring-2 focus:ring-sky-400/60"
            >
              Sign In
            </button>
            <button
              type="button"
              onClick={onClose}
              className="h-11 px-4 rounded-xl bg-slate-200 text-slate-700 hover:bg-slate-300"
            >
              Cancel
            </button>
          </div>

          <div className="mt-3 flex items-center justify-between">
            <button
              type="button"
              onClick={onSwitchToForgotUsername}   // ✅ wire to open ForgotUsernameModal
              className="text-xs text-sky-600 font-medium underline-offset-2 hover:underline"
            >
              Forgot Username
            </button>
            <button
              type="button"
              onClick={onSwitchToForgot}
              className="text-xs text-sky-600 font-medium underline-offset-2 hover:underline"
            >
              Forgot Password
            </button>
          </div>

          <hr className="my-6 border-slate-200/70" />
          <p className="text-slate-600 text-sm text-center">
            New here?{' '}
            <button
              type="button"
              onClick={onSwitchToSignUp}
              className="text-sky-600 hover:text-sky-700 underline-offset-2 hover:underline"
            >
              Create an account
            </button>
          </p>
        </form>
      </div>
    </div>
  );
};

export default SignInModal;
