// src/components/ForgotUsernameModal.jsx
import React, { useState } from "react";
import AuthLogo from "./AuthLogo.jsx";

const ForgotUsernameModal = ({ isOpen, onClose, onBack }) => {
  const [email, setEmail] = useState("");
  const [err, setErr] = useState("");
  const [info, setInfo] = useState("");

  if (!isOpen) return null;

  const send = async (e) => {
    e.preventDefault();
    setErr("");
    setInfo("");

    // Basic email check
    const okEmail = /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email);
    if (!okEmail) {
      setErr("Please enter a valid email address");
      return;
    }

    // Optional real email call if you wired a backend (see earlier message)
    const API = import.meta.env.VITE_API_URL;
    if (API) {
      try {
        await fetch(`${API}/auth/forgot-username`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ email }),
        });
      } catch (e) {
        // ignore network errors; still show generic success to prevent enumeration
      }
    }

    setInfo("If this email is registered, your username will be sent shortly.");
  };

  return (
    <div className="fixed inset-0 z-[1000] flex items-center justify-center bg-slate-950/60 backdrop-blur-sm">
      <div className="bg-white/95 backdrop-blur-md p-6 md:p-8 rounded-3xl shadow-2xl border border-slate-100 max-w-md w-full mx-4 relative">
        <button
          onClick={onClose}
          aria-label="Close modal"
          className="absolute top-3 right-3 w-9 h-9 grid place-items-center rounded-full bg-white/80 hover:bg-white shadow border border-slate-200 text-slate-600"
        >
          ✕
        </button>

        {/* Logo */}
        <AuthLogo size={96} />

        <form onSubmit={send}>
          <h2 className="text-2xl font-semibold text-slate-900 mb-1 text-center">
            Forgot Username
          </h2>
          <p className="text-sm text-slate-600 mb-5 text-center">
            Enter the email you signed up with. We’ll email your username if we find a match.
          </p>

          <div className="mb-4">
            <input
              type="email"
              placeholder="Email address"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full h-11 px-4 rounded-xl bg-white text-slate-900 placeholder-slate-400 ring-1 ring-slate-200 focus:ring-2 focus:ring-sky-400/60 focus:outline-none shadow-inner transition"
            />
          </div>

          {err && <p className="text-xs text-red-600 mt-1">{err}</p>}
          {info && <p className="text-xs text-green-600 mt-1">{info}</p>}

          <div className="flex justify-center gap-3 mt-3">
            <button
              type="submit"
              className="w-full h-11 rounded-xl bg-gradient-to-r from-indigo-600 to-sky-500 text-white font-semibold shadow-lg shadow-sky-500/20 hover:from-indigo-500 hover:to-sky-400 focus:outline-none focus:ring-2 focus:ring-sky-400/60"
            >
              Send Email
            </button>
            <button
              type="button"
              onClick={onBack}
              className="h-11 px-4 rounded-xl bg-slate-200 text-slate-700 hover:bg-slate-300"
            >
              Back
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default ForgotUsernameModal;
