// src/components/Footer.jsx
import React from "react";
import { Link } from "react-router-dom";
import tutorsimulaLogo from "../assets/tutorsimula-logo-purple.png";

function SocialIcon({ href, label, children }) {
  return (
    <a
      href={href}
      aria-label={label}
      target="_blank"
      rel="noreferrer"
      className="inline-flex h-9 w-9 items-center justify-center rounded-full border border-white/15 hover:border-white/40 hover:bg-white/5 transition"
    >
      {children}
    </a>
  );
}

export default function Footer() {
  const year = new Date().getFullYear();

  return (
    <footer className="mt-auto bg-[#0d1b2a] text-gray-300 rounded-t-[56px] overflow-hidden shadow-[0_-8px_24px_rgba(0,0,0,0.25)]">
      {/* Back to top */}
      <div className="text-center text-sm py-3 bg-[#12263a] hover:bg-[#15304a] transition">
        <a href="#" className="inline-block">Back to top</a>
      </div>

      {/* Top: Branding + Quick Nav + Contact */}
      <div className="max-w-7xl mx-auto px-6 py-10 grid gap-8 sm:grid-cols-2 lg:grid-cols-3">
        {/* Branding with animated logo (same as LaunchPage) */}
        <div>
          <div className="flex items-center gap-3">
            <img
              src={tutorsimulaLogo}
              alt="TutorSimula Logo"
              className="h-10 w-auto animate-logo animate-heartbeat"
              onError={(e) => {
                e.currentTarget.src =
                  "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=";
              }}
            />
            <span className="text-xl font-semibold text-white">TutorSimula</span>
          </div>
          <p className="mt-2 text-sm text-gray-300/80">
            Smart Avatars, Smarter Students
          </p>

          {/* Reuse the same keyframes used on LaunchPage */}
          <style>{`
            @keyframes swirlIn {
              0% { transform: rotate(90deg) scale(0); opacity: 0; }
              50% { transform: rotate(0deg) scale(1.1); opacity: 0.5; }
              100% { transform: rotate(0deg) scale(1); opacity: 1; }
            }
            @keyframes heartbeat {
              0% { transform: scale(1); }
              10% { transform: scale(1.05); }
              20% { transform: scale(1); }
              30% { transform: scale(1.03); }
              40% { transform: scale(1); }
              100% { transform: scale(1); }
            }
            .animate-logo { animation: swirlIn 1.5s ease-out forwards; }
            .animate-heartbeat { animation: heartbeat 2.5s ease-in-out infinite; }
            @media (prefers-reduced-motion: no-preference) {
              .animate-logo { animation: swirlIn 1.5s ease-out forwards; }
              .animate-heartbeat { animation: heartbeat 2.5s ease-in-out infinite; }
            }
          `}</style>
        </div>

        {/* Quick Navigation */}
        <div>
          <h3 className="text-white font-semibold mb-3">Quick Navigation</h3>
          <ul className="space-y-2 text-sm">
            <li><Link to="/" className="hover:text-white">Home</Link></li>
            <li><Link to="/about" className="hover:text-white">About</Link></li>
            <li><Link to="/programs" className="hover:text-white">Programs</Link></li>
            <li><Link to="/help" className="hover:text-white">Help</Link></li>
          </ul>
        </div>

        {/* Contact */}
        <div>
          <h3 className="text-white font-semibold mb-3">Contact</h3>
          <p className="text-sm mb-3">
            Email: <a className="underline hover:text-white" href="mailto:support@tutorsimula.com">support@tutorsimula.com</a>
          </p>
          <div className="flex items-center gap-3">
            {/* LinkedIn */}
            <SocialIcon href="https://www.linkedin.com/company/tutorsimula" label="LinkedIn">
              <svg viewBox="0 0 24 24" className="h-4 w-4 fill-current"><path d="M4.98 3.5A2.48 2.48 0 1 1 0 3.5a2.48 2.48 0 0 1 4.98 0zM.5 8h4v16h-4zM8 8h3.8v2.2h.1c.5-1 1.7-2.2 3.6-2.2 4.5 0 5.5 2.4 5.5 6.1V24h-4v-8.5c0-2-0.7-3.4-2.4-3.4-1.3 0-2.1.9-2.4 1.8-.1.3-.1.8-.1 1.3V24H8V8z"/></svg>
            </SocialIcon>
            {/* YouTube */}
            <SocialIcon href="https://www.youtube.com/@TutorSimula" label="YouTube">
              <svg viewBox="0 0 24 24" className="h-4 w-4 fill-current"><path d="M23.5 6.2a3 3 0 0 0-2.1-2.1C19.6 3.5 12 3.5 12 3.5s-7.6 0-9.4.6A3 3 0 0 0 .5 6.2C0 8 0 12 0 12s0 4 .5 5.8a3 3 0 0 0 2.1 2.1c1.8.6 9.4.6 9.4.6s7.6 0 9.4-.6a3 3 0 0 0 2.1-2.1C24 16 24 12 24 12s0-4-.5-5.8zM9.6 15.6V8.4L15.8 12l-6.2 3.6z"/></svg>
            </SocialIcon>
            {/* Twitter / X */}
            <SocialIcon href="https://x.com/tutorsimula" label="Twitter / X">
              <svg viewBox="0 0 24 24" className="h-4 w-4 fill-current"><path d="M18.244 2H21.5l-7.8 8.9L22.5 22h-6.3l-5-6-5.7 6H1.2l8.4-9.3L1 2h6.4l4.6 5.6L18.244 2zm-1.1 18h1.8L8.1 4H6.2l10.944 16z"/></svg>
            </SocialIcon>
            {/* Facebook */}
            <SocialIcon href="https://facebook.com/tutorsimula" label="Facebook">
              <svg viewBox="0 0 24 24" className="h-4 w-4 fill-current"><path d="M22 12a10 10 0 1 0-11.6 9.9v-7h-2.4V12h2.4V9.6c0-2.4 1.4-3.8 3.6-3.8 1 0 2 .2 2 .2v2.2h-1.1c-1.1 0-1.5.7-1.5 1.4V12h2.6l-.4 2.9h-2.2v7A10 10 0 0 0 22 12z"/></svg>
            </SocialIcon>
            {/* Instagram */}
            <SocialIcon href="https://instagram.com/tutorsimula" label="Instagram">
              <svg viewBox="0 0 24 24" className="h-4 w-4 fill-current"><path d="M7 2h10a5 5 0 0 1 5 5v10a5 5 0 0 1-5 5H7a5 5 0 0 1-5-5V7a5 5 0 0 1 5-5zm0 2a3 3 0 0 0-3 3v10a3 3 0 0 0 3 3h10a3 3 0 0 0 3-3V7a3 3 0 0 0-3-3H7zm5 3.5A5.5 5.5 0 1 1 6.5 13 5.5 5.5 0 0 1 12 7.5zm0 2A3.5 3.5 0 1 0 15.5 13 3.5 3.5 0 0 0 12 9.5zm6.25-3.75a1.25 1.25 0 1 1-1.25 1.25 1.25 1.25 0 0 1 1.25-1.25z"/></svg>
            </SocialIcon>
          </div>
        </div>
      </div>

      {/* Middle: Resources, Why Us, Business Solutions */}
      <div className="border-t border-white/10">
        <div className="max-w-7xl mx-auto px-6 py-10 grid gap-8 sm:grid-cols-2 lg:grid-cols-3">
          {/* Resources */}
          <div>
            <h3 className="text-white font-semibold mb-3">Resources</h3>
            <ul className="space-y-2 text-sm">
              <li><Link to="/resources/articles" className="hover:text-white">Articles</Link></li>
              <li><Link to="/resources/interview-questions" className="hover:text-white">Interview Questions</Link></li>
              <li><Link to="/resources/coding-problems" className="hover:text-white">Coding Problems</Link></li>
              <li><Link to="/learn" className="hover:text-white">Learn</Link></li>
              <li><Link to="/career-advice" className="hover:text-white">Career Advice</Link></li>
            </ul>
          </div>

          {/* Why Us */}
          <div>
            <h3 className="text-white font-semibold mb-3">Why Us</h3>
            <ul className="space-y-2 text-sm">
              <li><Link to="/why-us" className="hover:text-white">Why Us</Link></li>
              <li><Link to="/reviews" className="hover:text-white">Reviews</Link></li>
              <li><Link to="/avatars" className="hover:text-white">Avatars</Link></li>
              <li><Link to="/faq" className="hover:text-white">FAQs</Link></li>
            </ul>
          </div>

          {/* Business Solutions */}
          <div>
            <h3 className="text-white font-semibold mb-3">Business Solutions</h3>
            <ul className="space-y-2 text-sm">
              <li><Link to="/business" className="hover:text-white">For Business</Link></li>
              <li><Link to="/colleges" className="hover:text-white">For Colleges</Link></li>
              <li><Link to="/enterprise" className="hover:text-white">Enterprise</Link></li>
            </ul>
          </div>
        </div>
      </div>

      {/* Bottom: Legal */}
      <div className="bg-[#0b1625] border-t border-white/10">
        <div className="max-w-7xl mx-auto px-6 py-6 flex flex-col sm:flex-row items-center justify-between gap-4">
          <div className="text-xs sm:text-sm space-x-3 text-gray-400">
            <Link to="/privacy" className="hover:text-white">Privacy Policy</Link>
            <span className="hidden sm:inline">•</span>
            <Link to="/terms" className="hover:text-white">Terms of Service</Link>
          </div>
          <div className="text-[11px] text-gray-400">
            © {year} TutorSimula. All rights reserved.
          </div>
        </div>
      </div>
    </footer>
  );
}
