// src/pages/LaunchPage.jsx
import React, { useState } from "react";
import { useNavigate } from "react-router-dom";

import NavBar from "../NavBar.jsx";
import tutorsimulaLogo from "../assets/tutorsimula-logo-purple.png";

import Chatbot from "../components/Chatbot.jsx";
import SuccessStories from "../components/SuccessStories.jsx";
import Footer from "../components/Footer.jsx";
import SignInModal from "../components/SignInModal.jsx";
import SignUpModal from "../components/SignUpModal.jsx";
import ForgotPasswordModal from "../components/ForgotPasswordModal.jsx";
import ForgotUsernameModal from "../components/ForgotUsernameModal.jsx";

import successStories from "../data/successStories.js";
import { useAuth } from "../AuthContext.jsx";

const LaunchPage = () => {
  const navigate = useNavigate();
  const { user } = useAuth();

  // 'signin' | 'signup' | 'forgot' | 'forgot-username' | null
  const [modal, setModal] = useState(null);
  const [isChatbotOpen, setIsChatbotOpen] = useState(false);
  const toggleChatbot = () => setIsChatbotOpen((v) => !v);

  const handleStart = () => {
    if (user) navigate("/mock-interview");
    else setModal("signup");
  };

  return (
    <div className="min-h-screen bg-gray-800">
      {/* Top Nav */}
      <NavBar
        onSignIn={() => setModal("signin")}
        onSignUp={() => setModal("signup")}
      />

      <div className="flex-1 flex flex-col items-center px-6 py-8 pt-20 pb-32">
        <div className="w-full max-w-5xl mx-auto">
          {/* Hero */}
          <div className="bg-gray-800 text-white py-20 text-center rounded-lg shadow-lg mb-12">
            <img
              src={tutorsimulaLogo}
              alt="TutorSimula Logo"
              className="max-w-xs w-full h-auto mx-auto mb-6 animate-logo animate-heartbeat"
              onError={(e) => {
                e.currentTarget.src =
                  "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=";
              }}
            />
            <h1 className="text-4xl md:text-5xl font-bold mb-4">
              Master Technical Interviews with AI-Powered Practice
            </h1>
            <p className="text-lg md:text-xl mb-2">
              Land your dream tech job with personalized mock interviews and real-time feedback.
            </p>
            <p className="text-lg md:text-xl mb-6">Start Your Professional Journey Today</p>
            <button
              onClick={handleStart}
              className="bg-green-600 text-white px-6 py-3 rounded-lg text-lg font-semibold hover:bg-green-700 transform hover:scale-105 transition-all duration-300"
            >
              Start
            </button>

            <style>{`
              @keyframes swirlIn {
                0% { transform: rotate(90deg) scale(0); opacity: 0; }
                50% { transform: rotate(0deg) scale(1.1); opacity: 0.5; }
                100% { transform: rotate(0deg) scale(1); opacity: 1; }
              }
              @keyframes heartbeat {
                0% { transform: scale(1); }
                10% { transform: scale(1.05); }
                20% { transform: scale(1); }
                30% { transform: scale(1.03); }
                40% { transform: scale(1); }
                100% { transform: scale(1); }
              }
              .animate-logo { animation: swirlIn 1.5s ease-out forwards; }
              .animate-heartbeat { animation: heartbeat 2.5s ease-in-out infinite; }
              @media (prefers-reduced-motion: no-preference) {
                .animate-logo { animation: swirlIn 1.5s ease-out forwards; }
                .animate-heartbeat { animation: heartbeat 2.5s ease-in-out infinite; }
              }
            `}</style>
          </div>

          {/* Program Stages */}
          <div id="how-it-works" className="py-16 text-center rounded-lg mb-12">
            <h2 className="text-3xl font-bold text-white mb-8">Your Path to Interview Success</h2>
            <div className="grid grid-cols-1 md:grid-cols-5 gap-8 max-w-6xl mx-auto">
              {[
                { stage: "Nexus", desc: "Build foundational skills and resume confidence." },
                { stage: "Challenge", desc: "Tackle intermediate tasks and teamwork scenarios." },
                { stage: "Perform", desc: "Master advanced technical and leadership skills." },
                { stage: "Finish", desc: "Prove production-ready proficiency under pressure." },
                { stage: "Review", desc: "Polish soft skills and get career-ready feedback." },
              ].map((item, idx) => (
                <div key={idx} className="p-6 bg-white rounded-2xl shadow-xl border border-gray-100">
                  <div className="text-2xl font-semibold text-blue-900">{item.stage}</div>
                  <p className="mt-2 text-orange-600">{item.desc}</p>
                </div>
              ))}
            </div>
          </div>

          {/* USPs */}
          <div className="py-16 text-center mb-12">
            <h2 className="text-3xl font-bold text-white mb-8">Why Choose Mock Interview?</h2>
            <div className="grid grid-cols-1 md:grid-cols-4 gap-8 max-w-6xl mx-auto">
              {[
                { title: "AI-Powered Avatars", desc: "Get personalized guidance from lifelike tutors.", icon: "🤖" },
                { title: "Role-Specific Tracks", desc: "Tailored prep for Frontend, Backend, ML, and more.", icon: "🎯" },
                { title: "Real-Time Feedback", desc: "Instant insights to sharpen your skills.", icon: "⚡" },
                { title: "Immersive Tools", desc: "Code and whiteboard in a pro environment.", icon: "🛠️" },
              ].map((item, idx) => (
                <div key={idx} className="p-6">
                  <div className="text-4xl mb-4">{item.icon}</div>
                  <h3 className="text-xl font-semibold text-blue-400">{item.title}</h3>
                  <p className="mt-2 text-gray-300">{item.desc}</p>
                </div>
              ))}
            </div>
          </div>

          {/* Success Stories */}
          <SuccessStories stories={successStories} />
        </div>
      </div>

      {/* Auth Modals */}
      <SignInModal
        isOpen={modal === "signin"}
        onClose={() => setModal(null)}
        onSwitchToSignUp={() => setModal("signup")}
        onSwitchToForgot={() => setModal("forgot")}
        onSwitchToForgotUsername={() => setModal("forgot-username")}  // ✅ added
      />

      <SignUpModal
        isOpen={modal === "signup"}
        onClose={() => setModal(null)}
        onSwitchToSignIn={() => setModal("signin")}
      />

      <ForgotPasswordModal
        isOpen={modal === "forgot"}
        onClose={() => setModal(null)}
        onBack={() => setModal("signin")}
      />

      <ForgotUsernameModal
        isOpen={modal === "forgot-username"}
        onClose={() => setModal(null)}
        onBack={() => setModal("signin")}
      />

      {/* Chatbot */}
      <Chatbot isOpen={isChatbotOpen} toggleChatbot={toggleChatbot} />

      <Footer />
    </div>
  );
};

export default LaunchPage;
