// src/App.jsx
import React, { Suspense, lazy } from 'react';
import { Routes, Route, Navigate } from 'react-router-dom';
import LaunchPage from './pages/LaunchPage.jsx';

const AboutPage             = lazy(() => import('./components/AboutPage.jsx'));
const ProgramsPage          = lazy(() => import('./components/ProgramsPage.jsx'));
const HelpPage              = lazy(() => import('./components/HelpPage.jsx'));
const ProfilePage           = lazy(() => import('./components/ProfilePage.jsx'));
const CodeEditorPage        = lazy(() => import('./components/CodeEditorPage.jsx'));
const ProtectedRoute        = lazy(() => import('./components/ProtectedRoute.jsx'));
const MockInterviewComponent= lazy(() => import('./components/MockInterviewComponent.jsx'));
const TechnologySelection   = lazy(() => import('./components/TechnologySelection.jsx'));
const TermsAndConditions    = lazy(() => import('./components/TermsAndConditions.jsx'));
const ResumeUpload          = lazy(() => import('./components/ResumeUpload.jsx'));
const StagesInformation     = lazy(() => import('./components/StagesInformation.jsx'));

export default function App() {
  return (
    <Suspense fallback={<div style={{ color: '#fff', padding: 24 }}>Loading…</div>}>
      <Routes>
        <Route path="/" element={<LaunchPage />} />
        <Route path="/about" element={<AboutPage />} />
        <Route path="/programs" element={<ProgramsPage />} />
        <Route path="/help" element={<HelpPage />} />
        <Route path="/profile" element={<ProtectedRoute><ProfilePage /></ProtectedRoute>} />
        <Route path="/profile/:program" element={<ProtectedRoute><ProfilePage /></ProtectedRoute>} />
        <Route path="/code-editor" element={<ProtectedRoute><CodeEditorPage /></ProtectedRoute>} />
        <Route path="/profile/mock-interview" element={<MockInterviewComponent />} />
        <Route path="/technology-selection" element={<TechnologySelection />} />
        <Route path="/terms-and-conditions" element={<TermsAndConditions />} />
        <Route path="/mock-interview" element={<MockInterviewComponent />} />
        <Route path="/resume-upload" element={<ResumeUpload />} />
        <Route path="/stages-information" element={<StagesInformation />} />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </Suspense>
  );
}
