// src/NavBar.jsx
import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useAuth } from "./AuthContext.jsx";
import tutorsimulaLogo from "./assets/tutorsimula-logo-purple.png";

export default function NavBar({ onSignIn, onSignUp }) {
  const { user, signOut } = useAuth();
  const navigate = useNavigate();
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const handleSignOut = () => {
    signOut();
    navigate("/");
  };

  const toggleMenu = () => setIsMenuOpen((v) => !v);

  const fireSignIn = (e) => {
    e?.preventDefault?.();
    if (onSignIn) onSignIn();             // ✅ opens Sign In modal
    else navigate("/", { state: { showSignIn: true } });
  };

  const fireSignUp = (e) => {
    e?.preventDefault?.();
    if (onSignUp) onSignUp();             // ✅ opens Sign Up modal
    else navigate("/", { state: { showSignUp: true } });
  };

  return (
    <nav className="fixed top-0 w-full bg-gray-900 shadow-2g z-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center h-16">
          {/* Logo */}
          <div className="flex-shrink-0 flex items-center">
            <Link to="/" className="flex items-center">
              <img
                src={tutorsimulaLogo}
                alt="TutorSimula Logo"
                className="h-6 w-auto mr-2"
                onError={(e) => {
                  e.currentTarget.src =
                    "data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mNk+A8AAQUBAScY42YAAAAASUVORK5CYII=";
                }}
              />
              <span className="text-2xl font-bold text-white">TutorSimula</span>
            </Link>
          </div>

          {/* Desktop links */}
          <div className="hidden md:flex items-center space-x-4">
            <Link to="/" className="text-gray-200 hover:text-white px-3 py-2 rounded-md text-sm font-medium">
              Home
            </Link>
            <Link to="/about" className="text-gray-200 hover:text-white px-3 py-2 rounded-md text-sm font-medium">
              About
            </Link>
            <Link to="/programs" className="text-gray-200 hover:text-white px-3 py-2 rounded-md text-sm font-medium">
              Programs
            </Link>
            <Link to="/help" className="text-gray-200 hover:text-white px-3 py-2 rounded-md text-sm font-medium">
              Help
            </Link>

            {user ? (
              <button
                type="button"
                onClick={handleSignOut}
                className="bg-gradient-to-r from-red-600 to-red-800 text-white px-4 py-2 rounded-lg text-sm font-semibold hover:from-red-700 hover:to-red-900 transition"
              >
                Sign Out
              </button>
            ) : (
              <div className="flex space-x-2">
                <button
                  type="button"
                  onClick={fireSignIn}   // ✅ Sign In opens Sign In modal
                  className="bg-gradient-to-r from-blue-600 to-blue-800 text-white px-4 py-2 rounded-lg text-sm font-semibold hover:from-blue-700 hover:to-blue-900 transition"
                >
                  Sign In
                </button>
                <button
                  type="button"
                  onClick={fireSignUp}   // ✅ Sign Up opens Sign Up modal
                  className="bg-gradient-to-r from-green-600 to-green-800 text-white px-4 py-2 rounded-lg text-sm font-semibold hover:from-green-700 hover:to-green-900 transition"
                >
                  Sign Up
                </button>
              </div>
            )}
          </div>

          {/* Mobile menu toggle */}
          <div className="md:hidden flex items-center">
            <button onClick={toggleMenu} className="text-gray-200 hover:text-white focus:outline-none" type="button">
              <svg className="h-6 w-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                {isMenuOpen ? (
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
                ) : (
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 6h16M4 12h16M4 18h16" />
                )}
              </svg>
            </button>
          </div>
        </div>

        {/* Mobile menu */}
        {isMenuOpen && (
          <div className="md:hidden">
            <div className="px-2 pt-2 pb-3 space-y-1 sm:px-3">
              <Link to="/" onClick={toggleMenu} className="text-gray-200 hover:text-white block px-3 py-2 rounded-md text-base font-medium">
                Home
              </Link>
              <Link to="/about" onClick={toggleMenu} className="text-gray-200 hover:text-white block px-3 py-2 rounded-md text-base font-medium">
                About
              </Link>
              <Link to="/programs" onClick={toggleMenu} className="text-gray-200 hover:text-white block px-3 py-2 rounded-md text-base font-medium">
                Programs
              </Link>
              <Link to="/help" onClick={toggleMenu} className="text-gray-200 hover:text-white block px-3 py-2 rounded-md text-base font-medium">
                Help
              </Link>

              {user ? (
                <button
                  type="button"
                  onClick={() => {
                    handleSignOut();
                    toggleMenu();
                  }}
                  className="bg-gradient-to-r from-red-600 to-red-800 text-white block w-full text-left px-3 py-2 rounded-md text-base font-medium hover:from-red-700 hover:to-red-900 transition"
                >
                  Sign Out
                </button>
              ) : (
                <>
                  <button
                    type="button"
                    onClick={(e) => {
                      fireSignIn(e);       // ✅
                      toggleMenu();
                    }}
                    className="bg-gradient-to-r from-blue-600 to-blue-800 text-white block w-full text-left px-3 py-2 rounded-md text-base font-medium hover:from-blue-700 hover:to-blue-900 transition"
                  >
                    Sign In
                  </button>
                  <button
                    type="button"
                    onClick={(e) => {
                      fireSignUp(e);       // ✅
                      toggleMenu();
                    }}
                    className="bg-gradient-to-r from-green-600 to-green-800 text-white block w-full text-left px-3 py-2 rounded-md text-base font-medium hover:from-green-700 hover:to-green-900 transition"
                  >
                    Sign Up
                  </button>
                </>
              )}
            </div>
          </div>
        )}
      </div>
    </nav>
  );
}
