// src/AuthContext.js
import React, { createContext, useContext, useEffect, useMemo, useState } from "react";

/**
 * Very light auth store using localStorage:
 * - Users saved under key "ts_users" as an object map: { [username]: { username, name, email, password } }
 * - Current session saved under key "ts_current_user"
 * NOTE: For production, replace with secure, server-side auth.
 */

const USERS_KEY = "ts_users";
const CURRENT_USER_KEY = "ts_current_user";

const AuthContext = createContext(null);

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);       // { username, name, email }
  const [loading, setLoading] = useState(true); // reserved if you later add async init

  // Load current session at boot
  useEffect(() => {
    try {
      const raw = localStorage.getItem(CURRENT_USER_KEY);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (parsed?.username) setUser(parsed);
      }
    } catch (e) {
      console.warn("Auth init failed:", e);
    } finally {
      setLoading(false);
    }
  }, []);

  const readUsers = () => {
    try {
      const raw = localStorage.getItem(USERS_KEY);
      return raw ? JSON.parse(raw) : {};
    } catch {
      return {};
    }
  };

  const writeUsers = (users) => {
    localStorage.setItem(USERS_KEY, JSON.stringify(users));
  };

  /**
   * signUp(username, password, name, email) -> boolean
   * - returns false if username already exists
   */
  const signUp = (username, password, name, email) => {
    if (!username || !password || !name || !email) return false;

    const users = readUsers();
    const key = String(username).toLowerCase();

    if (users[key]) {
      // username taken
      return false;
    }

    users[key] = {
      username: key,
      name,
      email,
      // WARNING: stored in plain text for demo; replace with server-side hashing in real app
      password,
      createdAt: Date.now(),
    };

    writeUsers(users);

    // Auto-login after sign up (optional; matches your current flow)
    const sessionUser = { username: key, name, email };
    localStorage.setItem(CURRENT_USER_KEY, JSON.stringify(sessionUser));
    setUser(sessionUser);

    return true;
  };

  /**
   * signIn(username, password) -> boolean
   * - returns true if credentials match a saved user
   */
  const signIn = (username, password) => {
    if (!username || !password) return false;

    const users = readUsers();
    const key = String(username).toLowerCase();
    const u = users[key];

    if (!u || u.password !== password) {
      return false;
    }

    const sessionUser = { username: u.username, name: u.name, email: u.email };
    localStorage.setItem(CURRENT_USER_KEY, JSON.stringify(sessionUser));
    setUser(sessionUser);
    return true;
  };

  const signOut = () => {
    localStorage.removeItem(CURRENT_USER_KEY);
    setUser(null);
  };

  const value = useMemo(
    () => ({ user, loading, signIn, signUp, signOut }),
    [user, loading]
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
};

export const useAuth = () => useContext(AuthContext);
export default AuthContext;
